using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers;

public static class TestDbContextFactory
{
    public static SchoolContext Create(string? dbName = null)
    {
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
            .Options;

        var context = new SchoolContext(options);
        context.Database.EnsureCreated();
        return context;
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests
{
    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesCorrectMessage()
    {
        // Arrange
        var service = new NotificationService();

        // Act
        service.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Course", "101", EntityOperation.UPDATE, "Teacher");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 101", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_Delete_GeneratesDeleteMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Engineering", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "1", EntityOperation.CREATE, null);

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var service = new NotificationService();

        // Drain any existing messages from the static queue
        while (service.ReceiveNotification() != null) { }

        var result = service.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void SendAndReceive_MultipleNotifications_ReturnsFIFOOrder()
    {
        var service = new NotificationService();
        // Drain existing
        while (service.ReceiveNotification() != null) { }

        service.SendNotification("A", "1", EntityOperation.CREATE);
        service.SendNotification("B", "2", EntityOperation.UPDATE);
        service.SendNotification("C", "3", EntityOperation.DELETE);

        var first = service.ReceiveNotification();
        var second = service.ReceiveNotification();
        var third = service.ReceiveNotification();

        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
        Assert.Equal("C", third!.EntityType);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var service = new NotificationService();

        // Should not throw (no-op implementation)
        var exception = Record.Exception(() => service.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }
}

namespace ContosoUniversity.Tests.Helpers;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_MiddlePage_HasBothNavigation()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(2, result.PageIndex);
        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_LastPage_HasNoPreviousOnly()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(3, result.PageIndex);
        Assert.True(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_SinglePage_NoPagination()
    {
        var source = Enumerable.Range(1, 5).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyPage()
