using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
        _controller.TempData = new TempDataDictionary(new DefaultHttpContext(), new Mock_ITempDataProvider());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { ID = 1, LastName = "Adams", FirstMidName = "Alice", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { ID = 2, LastName = "Baker", FirstMidName = "Bob", EnrollmentDate = new DateTime(2021, 1, 15) },
            new Student { ID = 3, LastName = "Clark", FirstMidName = "Carol", EnrollmentDate = new DateTime(2019, 6, 1) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
    {
        SeedStudents();

        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
        Assert.Equal("Adams", model[0].LastName);
        Assert.Equal("Baker", model[1].LastName);
        Assert.Equal("Clark", model[2].LastName);
    }

    [Fact]
    public void Index_NameDesc_ReturnsStudentsInDescendingOrder()
    {
        SeedStudents();

        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Clark", model[0].LastName);
        Assert.Equal("Baker", model[1].LastName);
        Assert.Equal("Adams", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_ReturnsStudentsOrderedByEnrollmentDate()
    {
        SeedStudents();

        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Clark", model[0].LastName); // 2019
        Assert.Equal("Adams", model[1].LastName); // 2020
        Assert.Equal("Baker", model[2].LastName); // 2021
    }

    [Fact]
    public void Index_DateDescSort_ReturnsStudentsInDescendingDateOrder()
    {
        SeedStudents();

        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Baker", model[0].LastName); // 2021
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByLastName()
    {
        SeedStudents();

        var result = _controller.Index(null, null, "Baker", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Baker", model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByFirstName()
    {
        SeedStudents();

        var result = _controller.Index(null, null, "Alice", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Adams", model[0].LastName);
    }

    [Fact]
    public void Index_SearchStringResetsPage()
    {
        SeedStudents();

        var result = _controller.Index(null, null, "Adams", 3) as ViewResult;

        // When searchString is not null, page resets to 1
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        SeedStudents();
        // Add enrollment for Include test
        _context.Courses.Add(new Course { CourseID = 100, Title = "Math", Credits = 3, DepartmentID = 0 });
        _context.Enrollments.Add(new Enrollment { EnrollmentID = 1, StudentID = 1, CourseID = 100 });
        _context.SaveChanges();

        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Adams", student.LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithStudentWithTodayDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_AddsAndRedirects()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(_context.Students);
        Assert.Equal("Test", _context.Students.First().LastName);
    }

    [Fact]
    public void Create_Post_InvalidEnrollmentDate_ReturnsView()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_EnrollmentDateOutOfRange_ReturnsView()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(1000, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        SeedStudents();

        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Adams", student.LastName);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Edit_Get_NotFound_Returns404()
    {
        var result = _controller.Edit(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidStudent_UpdatesAndRedirects()
    {
        SeedStudents();

        var student = new Student
        {
            ID = 1,
            LastName = "Updated",
            FirstMidName = "Alice",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };
        // Detach the tracked entity
        _context.ChangeTracker.Clear();

        var result = _controller.Edit(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        _context.ChangeTracker.Clear();
        Assert.Equal("Updated", _context.Students.Find(1)!.LastName);
    }

    [Fact]
    public void Edit_Post_InvalidEnrollmentDate_ReturnsView()
    {
        var student = new Student
        {
            ID = 1,
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = default
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        SeedStudents();

        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Adams", student.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_NotFound_Returns404()
    {
        var result = _controller.Delete(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        SeedStudents();

        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(2, _context.Students.Count());
        Assert.Null(_context.Students.Find(1));
    }
}

// Minimal ITempDataProvider for controller tests
internal class Mock_ITempDataProvider : ITempDataProvider
{
    private Dictionary<string, object?> _data = new();
    public IDictionary<string, object?> LoadTempData(HttpContext context) => _data;
    public void SaveTempData(HttpContext context, IDictionary<string, object?> values) => _data = new Dictionary<string, object?>(values!);
}

