using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new DepartmentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedData()
    {
        _context.Instructors.Add(new Instructor
        {
            ID = 1, LastName = "Smith", FirstMidName = "John", HireDate = new DateTime(2015, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        });
        _context.Departments.AddRange(
            new Department { DepartmentID = 1, Name = "Engineering", Budget = 200000, StartDate = new DateTime(2010, 9, 1), InstructorID = 1 },
            new Department { DepartmentID = 2, Name = "Science", Budget = 150000, StartDate = new DateTime(2012, 1, 1) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_ReturnsAllDepartments()
    {
        SeedData();

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var departments = Assert.IsAssignableFrom<List<Department>>(result.Model);
        Assert.Equal(2, departments.Count);
    }

    [Fact]
    public void Details_ValidId_ReturnsDepartment()
    {
        SeedData();

        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Details_NotFound_Returns404()
    {
        var result = _controller.Details(999) as NotFoundResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Get_ReturnsView()
    {
        SeedData();

        var result = _controller.Create() as ViewResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Post_ValidDepartment_SavesAndRedirects()
    {
        SeedData();
        var dept = new Department { Name = "Math", Budget = 100000, StartDate = new DateTime(2020, 1, 1), InstructorID = 1 };

        var result = _controller.Create(dept) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(3, _context.Departments.Count());
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        SeedData();
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { Budget = 100000, StartDate = DateTime.Now };

        var result = _controller.Create(dept) as ViewResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsView()
    {
        SeedData();

        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Edit_Get_NotFound_Returns404()
    {
        var result = _controller.Edit(999) as NotFoundResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidDepartment_UpdatesAndRedirects()
    {
        SeedData();
        _context.ChangeTracker.Clear();
        var dept = new Department { DepartmentID = 1, Name = "Updated Engineering", Budget = 250000, StartDate = new DateTime(2010, 9, 1), InstructorID = 1 };

        var result = _controller.Edit(dept) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        _context.ChangeTracker.Clear();
        Assert.Equal("Updated Engineering", _context.Departments.Find(1)!.Name);
    }

    [Fact]
    public void Edit_Post_InvalidModel_ReturnsView()
    {
        SeedData();
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { DepartmentID = 1, Budget = 100000, StartDate = DateTime.Now };

        var result = _controller.Edit(dept) as ViewResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        SeedData();

        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Delete_Get_NotFound_Returns404()
    {
        var result = _controller.Delete(999) as NotFoundResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_RemovesDepartmentAndRedirects()
    {
        SeedData();

        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
