using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedData()
    {
        var dept = new Department { DepartmentID = 1, Name = "CS", Budget = 100000, StartDate = new DateTime(2010, 1, 1) };
        _context.Departments.Add(dept);

        var course1 = new Course { CourseID = 101, Title = "Intro CS", Credits = 3, DepartmentID = 1 };
        var course2 = new Course { CourseID = 102, Title = "Advanced CS", Credits = 4, DepartmentID = 1 };
        _context.Courses.AddRange(course1, course2);

        var instructor = new Instructor
        {
            ID = 1,
            LastName = "Fakhouri",
            FirstMidName = "Fadi",
            HireDate = new DateTime(2015, 3, 11),
            OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Smith 17" },
            CourseAssignments = new List<CourseAssignment>
            {
                new CourseAssignment { CourseID = 101, InstructorID = 1 }
            }
        };
        _context.Instructors.Add(instructor);

        var instructor2 = new Instructor
        {
            ID = 2,
            LastName = "Harui",
            FirstMidName = "Roger",
            HireDate = new DateTime(2018, 7, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor2);
        _context.SaveChanges();
    }

    [Fact]
    public void Index_NoParams_ReturnsViewWithAllInstructors()
    {
        SeedData();

        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var viewModel = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result.Model);
        Assert.Equal(2, viewModel.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        SeedData();

        var result = _controller.Index(1, null) as ViewResult;

        var viewModel = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result!.Model);
        Assert.NotNull(viewModel.Courses);
        Assert.Single(viewModel.Courses);
        Assert.Equal("Intro CS", viewModel.Courses.First().Title);
    }

    [Fact]
    public void Index_WithCourseId_PopulatesEnrollments()
    {
        SeedData();
        // Add an enrollment
        _context.Students.Add(new Student { ID = 10, LastName = "Doe", FirstMidName = "Jane", EnrollmentDate = DateTime.Now });
        _context.Enrollments.Add(new Enrollment { EnrollmentID = 1, CourseID = 101, StudentID = 10, Grade = Grade.A });
        _context.SaveChanges();

        var result = _controller.Index(1, 101) as ViewResult;

        var viewModel = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result!.Model);
        Assert.NotNull(viewModel.Enrollments);
        Assert.Single(viewModel.Enrollments);
    }

    [Fact]
    public void Details_ValidId_ReturnsInstructor()
    {
        SeedData();

        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Fakhouri", instructor.LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Details_NotFound_Returns404()
    {
        var result = _controller.Details(999) as NotFoundResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        SeedData();

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(instructor.CourseAssignments);
        Assert.Empty(instructor.CourseAssignments);
    }

    [Fact]
    public void Create_Post_ValidInstructor_SavesAndRedirects()
    {
        SeedData();
        var instructor = new Instructor
        {
            LastName = "New",
            FirstMidName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(3, _context.Instructors.Count());
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AssignsCourses()
    {
        SeedData();
        var instructor = new Instructor
        {
            LastName = "New",
            FirstMidName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, new[] { "101", "102" }) as RedirectToActionResult;

        Assert.NotNull(result);
        var saved = _context.Instructors.OrderBy(i => i.ID).Last();
        Assert.Equal(2, _context.CourseAssignments.Count(ca => ca.InstructorID == saved.ID));
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        SeedData();
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as ViewResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsView()
    {
        SeedData();

        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Fakhouri", instructor.LastName);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null) as StatusCodeResult;
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        SeedData();

        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Fakhouri", instructor.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Delete_Get_NotFound_Returns404()
    {
        var result = _controller.Delete(999) as NotFoundResult;
        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_RemovesInstructorAndClearsDepartmentFK()
    {
        SeedData();
        // Set instructor as department admin
        var dept = _context.Departments.Find(1)!;
        dept.InstructorID = 1;
        _context.SaveChanges();

        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Instructors.Find(1));
        _context.ChangeTracker.Clear();
        Assert.Null(_context.Departments.Find(1)!.InstructorID);
    }
}

