using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestDbContextFactory.Create();
    }

    public void Dispose() => _context.Dispose();

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        var student = new Student { LastName = "Doe", FirstMidName = "John", EnrollmentDate = new DateTime(2023, 1, 1) };
        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.First();
        Assert.Equal("Doe", retrieved.LastName);
        Assert.Equal("John", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddAndRetrieveCourseWithDepartment()
    {
        var dept = new Department { DepartmentID = 1, Name = "CS", Budget = 50000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        var course = new Course { CourseID = 100, Title = "Intro", Credits = 3, DepartmentID = 1 };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Include(c => c.Department).First();
        Assert.Equal("Intro", retrieved.Title);
        Assert.Equal("CS", retrieved.Department.Name);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        var dept = new Department { DepartmentID = 1, Name = "CS", Budget = 50000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = 1 };
        _context.Courses.Add(course);
        var instructor = new Instructor { ID = 1, LastName = "Test", FirstMidName = "Prof", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        _context.CourseAssignments.Add(new CourseAssignment { CourseID = 100, InstructorID = 1 });
        _context.SaveChanges();

        var ca = _context.CourseAssignments.Find(100, 1);
        Assert.NotNull(ca);
    }

    [Fact]
    public void Instructor_CanHaveOfficeAssignment()
    {
        var instructor = new Instructor
        {
            ID = 1, LastName = "Smith", FirstMidName = "Jane", HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" }
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.Include(i => i.OfficeAssignment).First();
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Enrollment_LinksStudentAndCourse()
    {
        var dept = new Department { DepartmentID = 1, Name = "CS", Budget = 50000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = 1 };
        _context.Courses.Add(course);
        var student = new Student { ID = 1, LastName = "Doe", FirstMidName = "Jane", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        _context.Enrollments.Add(new Enrollment { EnrollmentID = 1, CourseID = 100, StudentID = 1, Grade = Grade.B });
        _context.SaveChanges();

        var enrollment = _context.Enrollments.Include(e => e.Course).Include(e => e.Student).First();
        Assert.Equal("Test", enrollment.Course.Title);
        Assert.Equal("Doe", enrollment.Student.LastName);
        Assert.Equal(Grade.B, enrollment.Grade);
    }

    [Fact]
    public void Person_FullName_ConcatenatesLastAndFirst()
    {
        var student = new Student { LastName = "Garcia", FirstMidName = "Maria", EnrollmentDate = DateTime.Now };
        Assert.Equal("Garcia, Maria", student.FullName);
    }

    [Fact]
    public void Department_CanHaveNullAdministrator()
    {
        var dept = new Department { DepartmentID = 1, Name = "English", Budget = 75000, StartDate = DateTime.Now, InstructorID = null };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var retrieved = _context.Departments.Include(d => d.Administrator).First();
        Assert.Null(retrieved.Administrator);
    }

    [Fact]
    public void Notification_CanBeStoredAndRetrieved()
    {
        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test message",
            CreatedAt = DateTime.Now,
            CreatedBy = "Admin",
            IsRead = false
        };
        _context.Notifications.Add(notification);
        _context.SaveChanges();

        var retrieved = _context.Notifications.First();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("CREATE", retrieved.Operation);
        Assert.False(retrieved.IsRead);
    }
}

